      "type": "RULE",
      "force": "LEGAL",
      "force_from": "context (heading \"Regulatory signs\")",
      "text": "a driver MUST NOT pass on the road WHEN a \"do not pass\" sign is posted for the road",
      "sources": [
        {
          "id": "m25",
          "quote": "a regulatory sign"
        },
        {
          "id": "m26",
          "quote": "Do not pass on this road."
        }
