    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must keep right\")",
      "text": "a driver MUST keep right WHEN the driver is in [?slow traffic] on a multi-lane road",
      "sources": [
        {
          "id": "c8",
          "quote": "Slow traffic on multi-lane roads must keep right."
        },
        {
          "id": "c9",
          "quote": "a regulatory sign"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "slow traffic",
