        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "context (heading \"Regulatory signs\")",
      "text": "a driver MUST keep to the right lane WHEN a \"keep to the right lane\" sign is posted UNLESS the driver is passing on a two-lane section where climbing or passing lanes are provided",
      "sources": [
        {
          "id": "m30",
          "quote": "a regulatory sign"
        },
        {
          "id": "m31",
          "quote": "Keep to the right lane except when passing on two-lane sections where climbing or passing lanes are provided."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The caption contains no legal word, so the force comes from the 'Regulatory signs' heading. The exception is in the same passage as the rule, so it is an UNLESS clause."
    },
    {
      "id": "s4",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT the downward lines on a warning sign show the side on which a driver may [?safely] pass",
