        {
          "id": "m94",
          "quote": "The downward lines show the side on which you may safely pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safely",
          "note": "No measure of safety is given; the driver must judge the side."
        }
      ],
      "links": [],
      "note": "The caption describes what the sign's markings mean, so it is a FACT; the embedded 'may' (permission to pass on that side) is kept inside the fact."
    },
    {
