          "id": "m74",
          "quote": "a temporary condition sign"
        },
        {
          "id": "m75",
          "quote": "Do not pass the pilot vehicle or pace vehicle bearing this sign."
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "Do not pass",
          "note": "A plain 'do not pass' command reads like a legal prohibition, but the temporary condition signs section gives no legal wording in this batch, so it stays SHOULD NOT."
        }
      ],
      "links": [],
      "note": "The sign's own wording is not in the batch (the figure alt text is generic), so the condition names the sign by its instruction."
    },
